const validate = (): boolean => {
  const e: FormError = {};
  if (!form.courseId) e.courseId = 'يرجى اختيار المقرر المرجعي';
  if (!form.moduleId) e.moduleId = 'يرجى تحديد الوحدة التي ينتمي لها الدرس';
  if (!form.title.trim()) e.title = 'عنوان الدرس مطلوب';
  else if (form.title.trim().length < 2) e.title = 'يجب أن يكون عنوان الدرس حرفين على الأقل';
  if (!form.order.trim()) e.order = 'ترتيب الدرس مطلوب داخل الوحدة';
  else if (isNaN(Number(form.order)) || Number(form.order) < 1) e.order = 'يجب أن يكون الترتيب رقماً موجباً';

  // Content Validation
  if (form.type === 'video') {
    if (!form.videoUrl.trim()) e.submit = 'رابط الفيديو مطلوب في تبويب المحتوى';
    else if (!form.videoUrl.startsWith('http')) e.submit = 'رابط الفيديو غير صالح';
  } else if (form.type === 'markdown') {
    if (!form.content.trim()) e.submit = 'المحتوى النصي مطلوب في تبويب المحتوى';
  }
  if (form.pdfUrl.trim() && !form.pdfUrl.startsWith('http')) {
    e.submit = 'رابط الملف (PDF) غير صالح';
  }

  setErrors(e);
  if (Object.keys(e).length > 0 && e.submit) {
    setActiveTab('content'); // switch to content tab if errors are there
  }
  return Object.keys(e).length === 0;
};

